lab=load_lab()
# pair same set/model-ish, Adam vs AdamW low lr
from collections import defaultdict
groups=defaultdict(list)
for x in lab:
 o=x['optimizer']; m=x['model']
 if x['family']=='spiral_classification' and o['type'] in ('Adam','AdamW') and o['lr']<=1e-4:
  key=(x['set_id'],str(m),x['budget']['training_steps'],x['budget']['batch_size'])
  groups[key].append(x)
wins=ties=n=0; examples=[]
for k,rs in groups.items():
 a=[x for x in rs if x['optimizer']['type']=='Adam']; w=[x for x in rs if x['optimizer']['type']=='AdamW']
 for x in a:
  for y in w:
   n+=1
   if x['mean']<y['mean']: wins+=1
   elif x['mean']==y['mean']: ties+=1
   if len(examples)<5: examples.append((x['mean'],y['mean'],x['optimizer'],y['optimizer']))
print(n,wins,ties, "AdamW wins",n-wins-ties)
print(examples)
"}

